INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(107581, 'ruRU', '', 'Мне плевать на дружбу, мягкоземельный. Пока этот помогает нам проникнуть в гробницу, я буду терпеть его присутствие.', 24330),
(107584, 'ruRU', '', 'Твоя задача проста! Разберись с духами, пока я разбиваю обереги, запечатывающие гробницу.', 24330),
(107591, 'ruRU', '', 'Эти твари — лишь отвлекающий манёвр! К гробнице!', 24330),
(107604, 'ruRU', '', 'Я НЕ потеряю тебя!', 24330),
(107607, 'ruRU', '', 'Хватит болтовни. Вперёд!', 24330),
(107608, 'ruRU', '', 'Вода лунного колодца крайне важна. Не покидай Рощу Снов без неё! Я буду ждать твоего прибытия в Седых холмах.', 24330),
(107616, 'ruRU', '', 'Нет-нет. Я из Громового Утёса. Я искатель приключений, как и ты. Эти тавры Высокогорья чужды мне не меньше, чем тебе.\n\nОднако я увлечённый исследователь жизни Хална Высокогорье — одного из величайших тавров, когда-либо ступавших по этой земле. Пожалуй, самого величайшего. Здесь, в Высокогорье, у меня лучший шанс узнать о нём больше.', 26972),
(107617, 'ruRU', '', '%s взывает о помощи к существам поблизости.', 24330),
(107620, 'ruRU', '', 'Спасибо.', 24330),
(107622, 'ruRU', '', 'Поговори со мной, когда будешь готов уйти.', 24330),
(107624, 'ruRU', '', 'Всякий раз, когда меня одолевали сомнения, я спускалась в его курган. Я наблюдала за ним, пока он спал.', 24330),
(107625, 'ruRU', '', 'Даже во сне его присутствие успокаивало меня. Я оставляла свои страхи под землёй и выходила на поверхность, готовая вести свой народ.', 24330),
(107626, 'ruRU', '', 'Когда Малфурион вернулся ко мне, мы действовали как единое целое. Будто он никогда и не уходил. Доводилось ли тебе любить так, как люблю я?', 24330),
(107627, 'ruRU', '', 'Теперь Ксавий держит меня за горло. Мне придётся оставить возлюбленного и подчинить прекраснейшее создание, что я когда-либо знала.', 24330),
(107630, 'ruRU', '', 'Я сделаю всё необходимое, чтобы защитить Разлом Жуткого Шрама от Пылающего Легиона.', 24330),
(107631, 'ruRU', '', '<стонет> ...', 24330),
(107632, 'ruRU', '', 'Шинфел Верный Погибели бормочет бессвязно, явно от боли.', 24330),
(107634, 'ruRU', '', 'Скипетр Приливов... он здесь. Я нашёл его.', 24330),
(107635, 'ruRU', '', 'Они используют его, чтобы приводить существ этого мира в неистовство.', 24330),
(107636, 'ruRU', '', 'Шарас''дал держит у себя леди Зитрин. Она использовала меня как приманку.', 24330),
(107637, 'ruRU', '', 'Нам стоит повернуть назад. Весь этот мир — ловушка.', 24330),
(107642, 'ruRU', '', 'Ты опоздал! Он идёт...', 24330),
(107643, 'ruRU', '', 'Сохраните его душу целой. У Карии есть планы на этого.', 24330),
(107649, 'ruRU', '', 'Королева банши передаёт привет, $ct.', 24330),
(107655, 'ruRU', '', 'Я у тебя в долгу, мастер.', 24330),
(107656, 'ruRU', '', 'Будь осторожен. Этих врайкулов почти не остановить.', 24330),
(107657, 'ruRU', '', 'Я сам найду дорогу обратно в зал ордена. Спасибо.', 24330),
(107658, 'ruRU', '', 'Штормовое варево превращает врайкулов в жестокие, неостановимые машины. Будь осторожен.', 24330),
(107659, 'ruRU', '', 'Используй Штормовое варево, мастер. Это будет твоей единственной надеждой против них.', 24330),
(107661, 'ruRU', '', 'От этого места у меня мурашки по коже. Элуна, дай мне сил.', 24330),
(107662, 'ruRU', '', 'Теперь, когда у нас есть благословение Урсола, мы можем отправиться в Изумрудный Сон и вернуть когти! Идём, $n, не будем терять ни минуты!', 24330),
(107664, 'ruRU', '', 'Именно за этим мы тебя сюда привели. Уничтожь их!', 24330),
(107670, 'ruRU', '', 'Ещё враги!', 24330),
(107679, 'ruRU', '', 'Ты не из моей стаи. Что привело тебя в логово?', 24330),
(107697, 'ruRU', '', 'Отлично. Теперь помоги нам!', 24330),
(107701, 'ruRU', '', 'Эти проклятые близнецы... Они заплатят за то, что сделали!', 24330),
(107705, 'ruRU', '', 'Мелкие твари... вы снова сорвали мои планы.', 24330),
(107706, 'ruRU', '', 'Обещаю вам это, монахи Разрушенного храма... в следующую нашу встречу вы ЗАПЛАТИТЕ за свою дерзость!', 24330),
(107716, 'ruRU', '', 'Даргрул поймал в ловушку великую мать-василиска глубоко в хранилище. Если мы не прикончим её сейчас, он выйдет оттуда с армией обученных василисков!', 24330),
(107717, 'ruRU', '', 'Сегодня ты оказал племенам Высокогорья великую услугу.', 24330);
